'use client'

import { ButtonLink } from '@/registry/components/dashboardblocks/tooltip-link'
import { IconPlaceholder } from '@/registry/icons/icon-placeholder'
import type { ComponentProps } from 'react'

import { cn } from '@/lib/utils'

interface BlockFooterProps extends ComponentProps<'footer'> {
  /** Where to see more, such as the full report, drawn after the line with an arrow (the arrow alone in a block narrower than `@sm`). */
  link?: { href: string; label: string }
}

/**
 * One line under a block: a fact about what it shows, such as the best month, and a link to see
 * more. In `CardStyle`'s Frame it sits in the bottom rim of the card.
 */
function BlockFooter({ children, className, link, ...props }: BlockFooterProps) {
  return (
    <footer
      data-slot='block-footer'
      className={cn(
        'text-muted-foreground flex min-h-8 items-center justify-between gap-3 border-t pt-3 text-sm',
        className,
      )}
      {...props}
    >
      <p data-slot='block-footer-text' className='min-w-0 truncate'>
        {children}
      </p>
      {link && (
        <ButtonLink className='shrink-0' href={link.href} variant='ghost'>
          <span className='@max-sm:sr-only'>{link.label}</span>
          <IconPlaceholder
            lucide='ArrowRightIcon'
            tabler='IconArrowRight'
            hugeicons='ArrowRight01Icon'
            phosphor='ArrowRightIcon'
            remixicon='RiArrowRightLine'
            data-icon='inline-end'
          />
        </ButtonLink>
      )}
    </footer>
  )
}

export { BlockFooter }
export type { BlockFooterProps }
